#!/usr/bin/env python3

import sys
import re

def extract_hex_commands(script_file):
    hex_commands = []
    with open(script_file, 'r') as f:
        for line in f:
            if line.startswith('wx '):
                # Extract the hex part
                hex_part = line.strip().split(' ', 1)[1]
                # Remove 's+16' and trailing ';' if present
                hex_part = hex_part.split(';')[0]
                hex_commands.append(hex_part)
    return hex_commands

def decode_hex(hex_string):
    try:
        # Remove spaces and non-hex characters
        hex_clean = re.sub(r'[^0-9a-fA-F]', '', hex_string)
        # Convert hex to bytes then to ASCII
        return bytes.fromhex(hex_clean).decode('ascii', errors='replace')
    except Exception as e:
        return f"Error decoding: {e}"

if __name__ == "__main__":
    if len(sys.argv) != 2:
        print(f"Usage: {sys.argv[0]} <r2_script_file>")
        sys.exit(1)

    script_file = sys.argv[1]
    hex_commands = extract_hex_commands(script_file)

    print(f"Found {len(hex_commands)} hex commands")
    print("\nDecoded commands:")
    for i, cmd in enumerate(hex_commands):
        print(f"{i+1}: {decode_hex(cmd)}")

