#!/usr/bin/env python3

# Analyze the welcome2.r2 script to understand its functionality

import re

def extract_pieces():
    with open('/home/ctfplayer/ctf_files/welcome2.r2', 'r') as f:
        content = f.read()

    # Extract key parts
    macro_match = re.search(r'\(a,(.*?)\)', content)
    macro_def = macro_match.group(1) if macro_match else "Not found"

    hit_flags = re.findall(r'f hit\.\d+ = (\d+)', content)

    # Extract the wx commands and where they write to
    wx_commands = []
    for line in content.split('\n'):
        if line.startswith('wx '):
            parts = line.strip().split(' ', 1)[1].split('@')
            if len(parts) == 2:
                hex_data = parts[0].strip()
                location = parts[1].strip()
                wx_commands.append((hex_data, location))

    return {
        'macro_def': macro_def,
        'hit_flags': hit_flags,
        'wx_commands': wx_commands
    }

def decode_wx_commands(wx_commands):
    """Decode hex commands and organize them by location"""
    location_data = {}

    for hex_data, location in wx_commands:
        try:
            decoded = bytes.fromhex(hex_data).decode('utf-8', errors='replace')
            if location not in location_data:
                location_data[location] = []
            location_data[location].append((hex_data, decoded))
        except Exception as e:
            print(f"Error decoding {hex_data}: {e}")

    return location_data

def main():
    # Extract the pieces from the script
    pieces = extract_pieces()

    print("Macro definition:")
    print(pieces['macro_def'])
    print()

    print(f"Hit flags ({len(pieces['hit_flags'])}):")
    print(', '.join(pieces['hit_flags']))
    print()

    # Decode and organize wx commands
    location_data = decode_wx_commands(pieces['wx_commands'])

    print(f"Data written to different locations ({len(location_data)} locations):")
    for location, data_list in location_data.items():
        print(f"\n{location}:")
        for hex_data, decoded in data_list:
            print(f"  {hex_data} -> {decoded}")

    # Look for patterns that might form a flag
    print("\nLooking for flag patterns in decoded data...")
    for location, data_list in location_data.items():
        for hex_data, decoded in data_list:
            if '{' in decoded and '}' in decoded:
                print(f"Potential flag found: {decoded}")
            elif 'flag' in decoded.lower():
                print(f"Flag reference found: {decoded}")

if __name__ == "__main__":
    main()

